    segment_meta_->add_persisted_block(
        BlockMeta{block_id, BlockType::FTS_INDEX, 0, 0, 0, {}});
  } else {
    for (const auto &block : segment_meta_->persisted_blocks()) {
      if (block.type() == BlockType::FTS_INDEX) {
